using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class ServicoRepository(ProjetoIntegradorBackDbContext context):IServicoRepository{
public async Task<Result<Servico>> ObterPorIdAsync(Guid id,CancellationToken ct=default){try{var e=await context.Servicos.FindAsync(new object[]{id},ct);return e==null?Result<Servico>.AsFailure(new Failure(404,"Serviço não encontrado.")):Result<Servico>.AsSuccess(e);}catch(Exception ex){return Result<Servico>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Servico>>> ListarPorEstabelecimentoAsync(Guid id,CancellationToken ct=default){try{return Result<IReadOnlyList<Servico>>.AsSuccess(await context.Servicos.Where(x=>x.EstabelecimentoId==id&&x.Ativo).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Servico>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Servico>> AdicionarAsync(Servico e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();await context.Servicos.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Servico>.AsSuccess(e);}catch(Exception ex){return Result<Servico>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Servico>> AtualizarAsync(Servico e,CancellationToken ct=default){try{context.Servicos.Update(e);await context.SaveChangesAsync(ct);return Result<Servico>.AsSuccess(e);}catch(Exception ex){return Result<Servico>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<string>> DesativarAsync(Guid id,CancellationToken ct=default){try{var e=await context.Servicos.FindAsync(new object[]{id},ct);if(e==null)return Result<string>.AsFailure(new Failure(404,"Serviço não encontrado."));e.Ativo=false;await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Serviço desativado com sucesso.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}}